-- READ-ONLY rolling-window zero-run summary for source-only, interval=5 outTemp=0 rows. Runs require exact 300-second timestamp adjacency; duplicate archive copies are counted separately.
WITH zeros AS (SELECT 'old_weewx' source_name,a.dateTime ts,YEAR(FROM_UNIXTIME(a.dateTime)) utc_year,a.interval iv FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL AND a.outTemp=0 UNION ALL SELECT 'weewx_WH1080',a.dateTime,YEAR(FROM_UNIXTIME(a.dateTime)),a.interval FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL AND a.outTemp=0), eligible AS (SELECT * FROM zeros WHERE iv=5), lagged AS (SELECT source_name,ts,utc_year,LAG(ts) OVER(PARTITION BY source_name ORDER BY ts) prev_ts FROM eligible), marked AS (SELECT source_name,ts,utc_year,CASE WHEN prev_ts=ts-300 THEN 0 ELSE 1 END starts_run,SUM(CASE WHEN prev_ts=ts-300 THEN 0 ELSE 1 END) OVER(PARTITION BY source_name ORDER BY ts ROWS UNBOUNDED PRECEDING) run_id FROM lagged), runs AS (SELECT source_name,utc_year,run_id,COUNT(*) run_length_5m,MIN(ts) start_ts,MAX(ts) end_ts FROM marked GROUP BY source_name,utc_year,run_id) SELECT source_name,utc_year,COUNT(*) zero_run_count,SUM(run_length_5m) zero_rows_in_5m_runs,MAX(run_length_5m) max_consecutive_zero_rows,SUM(run_length_5m>=2) runs_ge_2,SUM(run_length_5m>=12) runs_ge_1h,SUM(run_length_5m>=288) runs_ge_24h FROM runs GROUP BY source_name,utc_year ORDER BY source_name,utc_year;
